package vn.edu.hcmute.khanggearver2.service.impl;
import java.math.BigDecimal; import java.util.Arrays; import java.util.EnumMap; import java.util.Map; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Service; import vn.edu.hcmute.khanggearver2.domain.OrderStatus; import vn.edu.hcmute.khanggearver2.repository.CategoryRepository; import vn.edu.hcmute.khanggearver2.repository.OrderRepository; import vn.edu.hcmute.khanggearver2.repository.ProductRepository; import vn.edu.hcmute.khanggearver2.repository.UserRepository; import vn.edu.hcmute.khanggearver2.service.StatisticsService; import vn.edu.hcmute.khanggearver2.service.StatisticsSummary;
@Service @Profile("!foundation") public class StatisticsServiceImpl implements StatisticsService { private final ProductRepository products; private final CategoryRepository categories; private final UserRepository users; private final OrderRepository orders; public StatisticsServiceImpl(ProductRepository p,CategoryRepository c,UserRepository u,OrderRepository o){products=p;categories=c;users=u;orders=o;} public StatisticsSummary summary(){Map<OrderStatus,Long> map=new EnumMap<>(OrderStatus.class);Arrays.stream(OrderStatus.values()).forEach(s->map.put(s,orders.countByOrderStatus(s)));return new StatisticsSummary(products.count(),products.countByActiveTrue(),products.countByStockLessThanEqual(5),categories.count(),users.count(),orders.count(),BigDecimal.ZERO,map);} }
